CREATE TABLE course_versions(id TEXT PRIMARY KEY,section_id TEXT NOT NULL REFERENCES sections(id),name TEXT NOT NULL,params TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','archived')),created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX course_section ON course_versions(section_id);
ALTER TABLE sections ADD COLUMN course_version TEXT REFERENCES course_versions(id);
ALTER TABLE assignments ADD COLUMN course_version TEXT REFERENCES course_versions(id);
ALTER TABLE assignments ADD COLUMN template_key TEXT;
ALTER TABLE assignments ADD COLUMN course_revision INTEGER;
ALTER TABLE assignments ADD COLUMN activity_type TEXT NOT NULL DEFAULT 'journal';
ALTER TABLE assignments ADD COLUMN activity_data TEXT;
CREATE UNIQUE INDEX course_exercise ON assignments(course_version,template_key);
CREATE TABLE course_snapshots(version_id TEXT NOT NULL REFERENCES course_versions(id),unit INTEGER NOT NULL,records TEXT NOT NULL,PRIMARY KEY(version_id,unit));
CREATE TABLE completions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),assignment_id TEXT NOT NULL REFERENCES assignments(id),answers TEXT NOT NULL,course_revision INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),UNIQUE(user_id,assignment_id));
ALTER TABLE attempts ADD COLUMN course_revision INTEGER;
CREATE TABLE course_edit_guards(version_id TEXT NOT NULL REFERENCES course_versions(id),revision INTEGER NOT NULL,PRIMARY KEY(version_id,revision));
CREATE TRIGGER course_edit_revision BEFORE INSERT ON course_edit_guards WHEN NEW.revision != (SELECT revision FROM course_versions WHERE id=NEW.version_id) BEGIN SELECT RAISE(ABORT,'Course revision conflict'); END;
CREATE TRIGGER course_content_frozen BEFORE UPDATE OF params ON course_versions WHEN EXISTS(SELECT 1 FROM attempts t JOIN assignments a ON a.id=t.assignment_id WHERE a.course_version=OLD.id) OR EXISTS(SELECT 1 FROM completions c JOIN assignments a ON a.id=c.assignment_id WHERE a.course_version=OLD.id) BEGIN SELECT RAISE(ABORT,'Course content is frozen'); END;
CREATE TRIGGER attempt_revision BEFORE INSERT ON attempts WHEN (SELECT course_version FROM assignments WHERE id=NEW.assignment_id) IS NOT NULL AND NEW.course_revision IS NOT (SELECT course_revision FROM assignments WHERE id=NEW.assignment_id) BEGIN SELECT RAISE(ABORT,'Course changed; refresh your assignment'); END;
CREATE TRIGGER completion_revision BEFORE INSERT ON completions WHEN NEW.course_revision IS NOT (SELECT course_revision FROM assignments WHERE id=NEW.assignment_id) BEGIN SELECT RAISE(ABORT,'Course changed; refresh your assignment'); END;
CREATE TRIGGER completions_no_update BEFORE UPDATE ON completions BEGIN SELECT RAISE(ABORT,'Completed work is immutable'); END;
CREATE TRIGGER completions_no_delete BEFORE DELETE ON completions BEGIN SELECT RAISE(ABORT,'Completed work is immutable'); END;
CREATE VIEW student_submissions AS SELECT id,user_id,assignment_id,created_at,'journal' AS kind FROM entries UNION ALL SELECT id,user_id,assignment_id,created_at,'activity' AS kind FROM completions;
INSERT OR IGNORE INTO accounts VALUES ('2070','Payroll taxes payable','liability','credit'),('5950','Payroll tax expense','expense','debit');
